-- A heap constraint outranks an index row: 18.6 checks the row's CHECK before it enters
-- any index, so an oversized key that also fails the CHECK is `23514`.
-- @setup
CREATE TABLE t (a text CHECK (length(a) < 10));
CREATE INDEX t_i ON t (a);
-- @test
-- @expect-error: the check constraint first
-- @expect-message
-- @profile-lock
INSERT INTO t VALUES ('');
